// Parse a number value. The parameter "text" must be zero terminated.
bool tryParseNumber(Value *pValue, const char *text, size_t textSize, bool stopAtNext) {
  NumberParser p = {
    (const unsigned char*) text,
    textSize,
    0,
    ' '
  };

  int leadingZeros = 0;
  bool testLeading = true;

  _next(&p);

  if (p.ch == '-') {
    _next(&p);
  }

  while (p.ch >= '0' && p.ch <= '9') {
    if (testLeading) {
      if (p.ch == '0') {
        leadingZeros++;
      } else {
        testLeading = false;
      }
    }
    _next(&p);
  }

  if (testLeading) {
    leadingZeros--;
  } // single 0 is allowed

  if (p.ch == '.') {
    while (_next(&p) && p.ch >= '0' && p.ch <= '9') {
    }
  }
  if (p.ch == 'e' || p.ch == 'E') {
    _next(&p);
    if (p.ch == '-' || p.ch == '+') {
      _next(&p);
    }
    while (p.ch >= '0' && p.ch <= '9') {
      _next(&p);
    }
  }

  auto end = p.indexNext;

  // skip white/to (newline)
  while (p.ch > 0 && p.ch <= ' ') {
    _next(&p);
  }

  if (stopAtNext) {
    // end scan if we find a punctuator character like ,}] or a comment
    if (p.ch == ',' || p.ch == '}' || p.ch == ']' ||
      p.ch == '#' || (p.indexNext < textSize && p.ch == '/' &&
      (p.data[p.indexNext] == '/' || p.data[p.indexNext] == '*')))
    {
      p.ch = 0;
    }
  }

  if (p.ch > 0 || leadingZeros != 0) {
    // Invalid number.
    return false;
  }

  std::int64_t i;
  if (_parseInt(&i, (char*) p.data, end - 1)) {
    *pValue = Value(i);
    return true;
  } else {
    double d;
    if (_parseFloat(&d, (char*) p.data, end - 1)) {
      *pValue = Value(d);
      return true;
    }
  }

  return false;
}

